{% extends 'base.html' %}{% block content %}
<h1>Tiket saya</h1><p><a href="{% url 'tiket-add' %}">Tambah tiket</a></p>
<ul>{% for item in object_list %}<li><h2>{{ item.judul }}</h2><p>{{ item.deskripsi }}</p><p>{{ item.get_status_display }}</p><a href="{% url 'tiket-edit' item.pk %}">Ubah tiket {{ item.pk }}</a>{% if item.status == 'terbuka' %}<form method="post" action="{% url 'tiket-close' item.pk %}">{% csrf_token %}<button type="submit">Selesaikan tiket {{ item.pk }}</button></form>{% endif %}</li>{% empty %}<li>Belum ada tiket milik Anda.</li>{% endfor %}</ul>
{% endblock %}

from django.contrib import admin
from .models import Perangkat, Tiket


@admin.register(Perangkat)
class PerangkatAdmin(admin.ModelAdmin):
    list_display = ['kode', 'nama', 'lokasi', 'aktif']
    search_fields = ['kode', 'nama', 'lokasi']
    list_filter = ['aktif']


@admin.register(Tiket)
class TiketAdmin(admin.ModelAdmin):
    list_display = ['judul', 'pemilik', 'status', 'dibuat']
    list_filter = ['status']
    search_fields = ['judul']
    readonly_fields = ['dibuat']

from django import forms
from .models import Perangkat, Tiket


class PerangkatForm(forms.ModelForm):
    class Meta:
        model = Perangkat
        fields = ['kode', 'nama', 'lokasi', 'aktif']

    def clean_kode(self):
        return self.cleaned_data['kode'].upper()


class TiketForm(forms.ModelForm):
    class Meta:
        model = Tiket
        fields = ['judul', 'deskripsi']  # Pemilik dan status ditentukan server.

